using System.Numerics;
using static AtlasPca.Mpc.NetPa;

namespace AtlasPca.Mpc.Net;

/// <summary>The offline material one party holds when the online phase starts, dealt by a trusted dealer or generated by the parties from OT.</summary>
public sealed class Prep
{
    /// <summary>The OT transcript of the triple products, kept to attribute a failed sacrifice (no-dealer mode only).</summary>
    public sealed record PrepForensics(BigInteger[] Gadget, int Rows, int Slots, Func<int, List<NetForensics.SlotDisclosure>> Disclose);

    /// <summary>"trusted-dealer" or "no-dealer". A trusted dealer knows every share and key.</summary>
    public readonly string Mode;
    /// <summary>Whether the shares carry pairwise tags (identifiable abort); only the trusted-dealer mode provides them.</summary>
    public readonly bool Tagged;
    public readonly BigInteger Delta;
    public readonly PA[] Alpha;
    /// <summary>Triples[t] = a, b, c, then (a-hat, c-hat) per sacrifice partner.</summary>
    public readonly AW[][] Triples;
    /// <summary>Authenticated masks (dealer) or input bits (no-dealer), indexed owner * C + chain.</summary>
    public readonly AW[] Inputs;
    public readonly BigInteger[] MyPlain;
    public readonly AW? CheckMask;
    public readonly PrepForensics? Forensics;

    public Prep(string mode, bool tagged, BigInteger delta, PA[] alpha, AW[][] triples, AW[] inputs, BigInteger[] myPlain, AW? checkMask, PrepForensics? forensics)
    {
        Mode = mode;
        Tagged = tagged;
        Delta = delta;
        Alpha = alpha;
        Triples = triples;
        Inputs = inputs;
        MyPlain = myPlain;
        CheckMask = checkMask;
        Forensics = forensics;
    }
}
